void mainImage(out vec4 O, vec2 u) {
    vec2 R = iResolution.xy,
        uv = u/R;

    O *= 0.;

    float[] gk1s = float[](
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.023792, 0.094907, 0.150342, 0.094907, 0.023792,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765
    );

    //golfed by fabriceneyret2
    for (int k; k < 25; k++)      
        O += gk1s[k] * texture(iChannel0, uv + ( vec2(k%5,k/5) - 2. ) / R );
}

// A very well polished band spectrum visualizer 
// with slowed fall rate caps by Orblivius one and only!
//
// Please feel free to improve, and I will gladly 
// integrate improvements.
//
// LICENSE: Freeware

#define COLS 32
#define ROWS 64

#define COLS_F float(COLS)
#define ROWS_F float(ROWS)

#define CMPR_PAL 1.2
#define FALL 0.005
#define V_OFFS 0.01

float bands[COLS], tops[COLS];

#define CAPS(xx)  (texture(iChannel1, vec2(xx,0.)).r)
#define CAPS1(xx) (bands[int(min(xx * COLS_F, COLS_F))] + V_OFFS)
#define CAPS2(xx) (bands[int(min(xx * COLS_F, COLS_F))])
#define TOPS1(xx) (tops[int(min(xx * COLS_F, COLS_F))] + V_OFFS)
#define TOPS2(xx) (tops[int(min(xx * COLS_F, COLS_F))])

float luma(in vec3 color) {
    return dot(color, vec3(0.299, 0.587, 0.114));
}
float sdRoundBox(vec2 p, vec2 b, float r)
{
  vec2 q = abs(p) - b;
  return length(max(q,.0)) + min(max(q.x,q.y),.0) - r;
}

 // returns 3 B-spline functions of degree 2

vec3 B2_spline(vec3 x) {
    vec3 t = 3.0 * x;
    vec3 b0 = step(0.0, t)     * step(0.0, 1.0-t);
	vec3 b1 = step(0.0, t-1.0) * step(0.0, 2.0-t);
	vec3 b2 = step(0.0, t-2.0) * step(0.0, 3.0-t);
	return 0.5 * (
    	b0 * pow(t, vec3(2.0)) +
    	b1 * (-2.0*pow(t, vec3(2.0)) + 6.0*t - 3.0) + 
    	b2 * pow(3.0-t,vec3(2.0))
    );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) 
{
    vec2 uv = fragCoord;
    uv.y = iResolution.y - uv.y;

    vec2 uvd = fragCoord.xy / iResolution.xy;
    vec2 nc = vec2(COLS, ROWS);

    if (fragCoord.y <= 1.) 
    {
       float fi = fragCoord.x;
       int i = int(fi);
       bands[i] = texture(iChannel0, vec2(fi / iResolution.x, .5/iResolution.y)).a;
       float val = texture(iChannel1, vec2(fi / iResolution.x, 0.)).r;
       vec4 col = vec4(max(max(bands[i]-FALL,0.),val));
       bands[i] = col.a;
       fragColor = vec4(0,0,0,col.r);
   } else{
        for (float i=0.; i<COLS_F; i++) {
           bands[int(i)] = texture(iChannel0, vec2(i / COLS_F, .5/iResolution.y)).a; 
           tops[int(i)] = texture(iChannel0, vec2(i / COLS_F, 1./iResolution.y)).a; 
        }

        vec2 ts = iResolution.xy / nc;
        vec2 fr = (fract(uv/ts)-0.5)*2.0;
        vec2 gr = floor(uv/ts);
        float d = sdRoundBox(fr, vec2(0.5, 0.5), 0.35);
        float a = smoothstep(0.09, 0.0, d);

        vec2 p;
        p.x = floor(uvd.x*nc.x)/nc.x;
        p.y = floor(uvd.y*nc.y)/nc.y - 0.1;

        vec3 spline_args = fract(vec3(uvd.y*CMPR_PAL-0.6)+ vec3(1.0, -1.0/3.0, -2.0/3.0));    
        vec3 spline = B2_spline(spline_args);

        float tt = 0.210 - uvd.y;
        float df = sign(tt);
        df = (df + 0.5)/0.5;

        float xNorm = floor(fragCoord.x / iResolution.x * nc.x) / nc.x;
        float yAtX = CAPS(xNorm);
        float yAtX2 = CAPS1(xNorm);
        float yAtX2c = CAPS2(xNorm);

        p.x = floor(uvd.x*nc.x)/nc.x;
        p.y = floor(uvd.y*nc.y)/nc.y - 0.15;
        vec2 cntr = vec2(0.5) * p - vec2(1.0);

        vec3 bcol  = vec3(1.0) - abs(cntr.y)*spline;
        vec3 fcol = pow(bcol, vec3(3.0));

        vec3 col = fcol * vec3(1.0 - step(yAtX, (0.3-p.y))) ;
        col -= col * df * 0.25;

        vec3 ccol = fcol * vec3(1.0 - step(0.0, (-0.3-2.*p.y))) ;
        ccol -= ccol * df * 0.2;

        spline_args = fract(vec3(yAtX2c*CMPR_PAL-0.6)+ vec3(1.0, -1.0/3.0, -2.0/3.0));    
        spline = B2_spline(spline_args);

        bcol  = vec3(1.0) - abs(cntr.y)*spline;
        fcol = pow(yAtX2, 1.8)*1.6*mix(10.*pow(bcol, vec3(5.)), vec3(1.0), 0.5);
        vec3 col2 = fcol * vec3(1.0 - step(yAtX2, (0.3-p.y))) ;
        col2 -= col2 * df * 0.25;

        float m1 = (p.y < yAtX) ? 1.0 : 0.0;
        float m2 = (p.y < yAtX2) ? 1.0 : 0.0;

        float sw = round(yAtX * nc.y) / nc.y;
        float sw1 = round(yAtX2 * nc.y) / nc.y;

        float up = step(1. - sw1, gr.y/nc.y);
        float mid = step(1. - sw1 , (gr.y/nc.y-0.01));
        float low = step(1. - sw, gr.y/nc.y);

        vec3 k = mix(vec3(0.), a*ccol, 0.07);
        vec3 z = mix(k, mix((col2), vec3(0.0), mid), 1.0);
        col += max(luma(col*col) - 1.0, 0.0);
        vec3 c = mix(z, col, a * low);
        fragColor = vec4(k + mix(vec3(0.), c, a * up), 1.0); 
    }


}
